using System;using System.Linq;using System.IO;using System.Threading.Tasks;using UnityEngine;using AntColony.Units;
public static class Native1112Cosmetics{public static async Task<string> Run(){var p=UnityEngine.Object.FindAnyObjectByType<MeshyNativeMotionPlayer>();var original=p.transform.Find("Kemono");var appearance=original.GetComponent<KemonoAppearance>();var source=original.GetComponentsInChildren<SkinnedMeshRenderer>();string oldHair=source.First(s=>s.enabled&&s.name.StartsWith("Part_Hair_")).name.Split('_')[2],oldOutfit=source.First(s=>s.enabled&&s.name.StartsWith("Part_Outfit_")).name.Split('_')[2];int count=0;var report=new System.Collections.Generic.List<string>();
 AntColony.UI.SimulationPause.UserSpeed(0);UnityEditor.EditorApplication.isPaused=false;try{foreach(var motion in new[]{"Idle_3","Heavy_Hammer_Swing"})foreach(var hair in appearance.GetVariants("Hair"))foreach(var outfit in appearance.GetVariants("Outfit")){appearance.SetVariant("Hair",hair);appearance.SetVariant("Outfit",outfit);p.PreviewMotion=motion;p.PreviewPhase=.3f;await Task.Delay(35);var skins=p.NativeModel.GetComponentsInChildren<SkinnedMeshRenderer>().Where(s=>s.enabled).ToArray();if(skins.Count(s=>s.name.StartsWith("Part_Hair_"))!=1||!skins.Any(s=>s.name=="Part_Hair_"+hair+"_00")||!skins.Any(s=>s.name=="Part_Outfit_"+outfit+"_00"))throw new Exception("Variant mismatch");count++;}
 var nativeFace=p.NativeModel.GetComponentsInChildren<SkinnedMeshRenderer>().First(s=>s.name.StartsWith("Part_Face_"));var face=source.First(s=>s.name.StartsWith("Part_Face_"));for(int i=0;i<face.sharedMesh.blendShapeCount;i++){face.SetBlendShapeWeight(i,75);p.NativeModel.GetComponent<MeshyNativeAppearance>().Sync();int index=nativeFace.sharedMesh.GetBlendShapeIndex(face.sharedMesh.GetBlendShapeName(i));if(index<0||nativeFace.GetBlendShapeWeight(index)!=75)throw new Exception("Expression mismatch");face.SetBlendShapeWeight(i,0);}
 report.Add(count+" combinations: 6 hair x 4 outfit material variants x 2 source rigs; one active hair/outfit PASS");report.Add(face.sharedMesh.blendShapeCount+" named facial shape channels sync PASS");File.WriteAllLines("work/animation-1112/cosmetics-checks.txt",report);return string.Join("\n",report);
 }finally{appearance.SetVariant("Hair",oldHair);appearance.SetVariant("Outfit",oldOutfit);p.PreviewMotion=null;p.PreviewPhase=-1;}}}
